<?php require_once '../config/auth.php'; require_role('kepala_sekolah'); $pdo=db(); $avg=$pdo->query('SELECT j.nama_jurusan,ROUND(AVG(n.nilai_akhir),2) rata FROM jurusan j JOIN kelas k ON k.id_jurusan=j.id_jurusan JOIN siswa s ON s.id_kelas=k.id_kelas LEFT JOIN nilai n ON n.nis=s.nis GROUP BY j.id_jurusan')->fetchAll(); $below=(int)$pdo->query('SELECT COUNT(*) FROM nilai WHERE nilai_akhir < 75')->fetchColumn(); $active=$pdo->query("SELECT * FROM tahun_ajaran WHERE status='Aktif' ORDER BY id_tahun_ajaran DESC LIMIT 1")->fetch(); $page_title='Dashboard Kepala Sekolah'; require '../includes/header.php';require '../includes/sidebar.php';require '../includes/flash.php'; ?><h2>Dashboard Kepala Sekolah</h2><div class="row g-3 mb-4"><div class="col-md-4"><div class="card stat p-3"><small>Nilai di bawah KKM (<?= DEFAULT_KKM ?>)</small><h2><?= $below ?></h2></div></div><div class="col-md-4"><div class="card stat p-3"><small>Tahun ajaran aktif</small><h5><?= e($active['tahun_ajaran']??'-') ?> · <?= e($active['semester']??'-') ?></h5></div></div></div><div class="card p-3"><h5>Rata-rata Nilai per Jurusan</h5><table class="table"><thead><tr><th>Jurusan</th><th>Rata-rata</th></tr></thead><tbody><?php foreach($avg as $r): ?><tr><td><?= e($r['nama_jurusan']) ?></td><td><?= e($r['rata']??'-') ?></td></tr><?php endforeach; ?></tbody></table></div><?php require '../includes/footer.php';
